CREATE TABLE public.videos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, camera_name text NOT NULL, camera_id text NOT NULL, location text NOT NULL, video_url text NOT NULL, recording_date date NOT NULL, start_time time NOT NULL, duration text NOT NULL DEFAULT '—', status text NOT NULL DEFAULT 'Not Indexed', created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.videos TO authenticated; GRANT ALL ON public.videos TO service_role; ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own videos" ON public.videos FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE TABLE public.investigations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, query text NOT NULL, evidence jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'Open', created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.investigations TO authenticated; GRANT ALL ON public.investigations TO service_role; ALTER TABLE public.investigations ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own investigations" ON public.investigations FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);